<style>
body{background:#faf9fc;font-family:Arial,sans-serif}.crud{max-width:1000px;margin:35px auto;padding:0 20px}.card{background:#fff;border-radius:20px;padding:30px;box-shadow:0 8px 30px rgba(30,40,60,.07)}h1{color:#4d2475;margin-top:0}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.campo.full{grid-column:1/-1}.campo label{display:block;font-weight:600;color:#172033;margin-bottom:7px}.campo input,.campo select,.campo textarea{width:100%;box-sizing:border-box;border:1px solid #dce2eb;border-radius:10px;padding:12px;font-size:15px}.campo textarea{min-height:110px;resize:vertical}.acoes{margin-top:25px;display:flex;gap:10px}.btn{border:0;border-radius:10px;padding:12px 20px;text-decoration:none;font-weight:600;cursor:pointer}.salvar{background:#7527d9;color:#fff}.voltar{background:#fff;color:#344054;border:1px solid #dce2eb}@media(max-width:700px){.grid{grid-template-columns:1fr}.campo.full{grid-column:auto}}
</style>
